INSERT INTO simulation_evaluations (user_id, q1, q2, q3, q4, q5, q6, q7, q8, q9, q10, answers, is_completed, completed_at, created_at, updated_at) VALUES ((SELECT id FROM users WHERE nama = 'responden100'), 4, 5, 5, 4, 5, 4, 4, 5, 5, 5, '{"1":{"orderNumber":1,"questionText":"Saya memahami prosedur simulasi perdagangan saham yang telah dilakukan","score":4,"label":"Setuju"},"2":{"orderNumber":2,"questionText":"Saya memahami simulasi aplikasi saham yang dipakai","score":5,"label":"Sangat Setuju"},"3":{"orderNumber":3,"questionText":"Saya memahami cara untuk memasukkan harga saham yang saya prediksi","score":5,"label":"Sangat Setuju"},"4":{"orderNumber":4,"questionText":"Saya memahami bahwa akan ada konsekuensi untung dan rugi dari prediksi harga saham yang saya berikan","score":4,"label":"Setuju"},"5":{"orderNumber":5,"questionText":"Simulasi aplikasi yang dipakai mudah dipahami dan digunakan","score":5,"label":"Sangat Setuju"},"6":{"orderNumber":6,"questionText":"Saya mengetahui ada informasi pada simulasi perdagangan saham ini","score":4,"label":"Setuju"},"7":{"orderNumber":7,"questionText":"Saya mengerti semua informasi (berita) yang muncul selama simulasi perdagangan saham","score":4,"label":"Setuju"},"8":{"orderNumber":8,"questionText":"Saya mengetahui setiap kali informasi (berita) muncul di layar aplikasi simulasi perdagangan saham","score":5,"label":"Sangat Setuju"},"9":{"orderNumber":9,"questionText":"Saya dapat membedakan informasi (berita) yang positif dan negatif selama simulasi perdagangan saham","score":5,"label":"Sangat Setuju"},"10":{"orderNumber":10,"questionText":"Informasi (berita) memengaruhi saya dalam memprediksi harga saham","score":5,"label":"Sangat Setuju"}}', true, '2026-11-13T17:54:56.520Z', NOW(), NOW()) ON CONFLICT (user_id) DO UPDATE SET q1 = EXCLUDED.q1, q2 = EXCLUDED.q2, q3 = EXCLUDED.q3, q4 = EXCLUDED.q4, q5 = EXCLUDED.q5, q6 = EXCLUDED.q6, q7 = EXCLUDED.q7, q8 = EXCLUDED.q8, q9 = EXCLUDED.q9, q10 = EXCLUDED.q10, answers = EXCLUDED.answers, is_completed = true, completed_at = EXCLUDED.completed_at, updated_at = NOW();
INSERT INTO portfolios (user_id, stock_id, jumlah_lot, average_price, created_at, updated_at) SELECT u.id, s.id, 10, s.base_price, NOW(), NOW() FROM users u, stocks s WHERE u.role = 'responden' ON CONFLICT (user_id, stock_id) DO NOTHING;
